[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode _:N62e51e22c3d14e32bd586ce4753093c6 ;
            sh:resultMessage "trainingRequired is false but an envelope entry has the trained-on role. Use derived-from for a reference dataset that was computed rather than fitted." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "trainingRequired is false but an envelope entry has the trained-on role. Use derived-from for a reference dataset that was computed rather than fitted." ;
                    sh:select """
      SELECT $this WHERE {
        $this <https://w3id.org/ogc/hosted/focal/transferability/properties/trainingRequired> false .
        $this <https://w3id.org/ogc/hosted/focal/transferability/properties/envelope> ?e .
        ?e <https://w3id.org/ogc/hosted/focal/transferability/properties/role>
           <https://w3id.org/ogc/hosted/focal/transferability/roles/trained-on> .
      }
    """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape focal-shape:NoTrainingMeansNoTrainedOn ;
            sh:value _:N62e51e22c3d14e32bd586ce4753093c6 ] .

_:N62e51e22c3d14e32bd586ce4753093c6 focal-prop:envelope <https://w3id.org/ogc/hosted/focal/transferability/examples/fp-wf4-fail/training#site> ;
    focal-prop:trainingRequired false .

